36  func (dp *DepProcessor) addDependency(gomod string, dependencies []Dependency) error {
37  	modfile, err := parseGoMod(gomod)
38  	if err != nil {
39  		return err
40  	}
41  	// For each dependency, check if it is already in the go.mod file and add
42  	// it using require directive. If the dependency specifies a replace path,
43  	// then further add a replace directive if it is not already in the go.mod
44  	changed := false
45  	for _, dependency := range dependencies {
46  		alreadyRequire := false
47  		for _, r := range modfile.Require {
48  			if r.Mod.Path == dependency.ImportPath {
49  				alreadyRequire = true
50  				break
51  			}
52  		}
53  		if !alreadyRequire {
54  			err = modfile.AddRequire(dependency.ImportPath, dependency.Version)
55  			if err != nil {
56  				return ex.Wrap(err)
57  			}
58  			changed = true
59  			util.Log("Add require dependency %s %s",
60  				dependency.ImportPath, dependency.Version)
61  		}
62  		if dependency.Replace {
63  			alreadyReplace := false
64  			for _, r := range modfile.Replace {
65  				if r.Old.Path == dependency.ImportPath {
66  					alreadyReplace = true
67  					break
68  				}
69  			}
70  			if !alreadyReplace {
71  				err = modfile.AddReplace(dependency.ImportPath, "",
72  					dependency.ReplacePath, dependency.ReplaceVersion)
73  				if err != nil {
74  					return ex.Wrap(err)
75  				}
76  				changed = true
77  				util.Log("Add replace dependency %s %s => %s %s",
78  					dependency.ImportPath, dependency.Version,
79  					dependency.ReplacePath, dependency.ReplaceVersion)
80  			}
81  		}
82  	}
83  	// Once all dependencies are added and write back to go.mod
84  	if changed {
85  		err = writeGoMod(gomod, modfile)
86  		if err != nil {
87  			return err
88  		}
89  	}
90  	return nil
