 98  func (i *InternalInstrumenter[REQUEST, RESPONSE]) doStart(parentContext context.Context, request REQUEST, timestamp time.Time, options ...trace.SpanStartOption) context.Context {
 99  	if i.enabler != nil && !i.enabler.Enable() {
100  		return parentContext
101  	}
102  	for _, listener := range i.operationListeners {
103  		parentContext = listener.OnBeforeStart(parentContext, timestamp)
104  	}
105  	// extract span name
106  	spanName := i.spanNameExtractor.Extract(request)
107  	spanKind := i.spanKindExtractor.Extract(request)
108  	options = append(options, trace.WithSpanKind(spanKind), trace.WithTimestamp(timestamp))
109  	newCtx, span := i.tracer.Start(parentContext, spanName, options...)
110  	attrs := make([]attribute.KeyValue, 0, 20)
111  	// extract span attrs
112  	for _, extractor := range i.attributesExtractors {
113  		attrs, newCtx = extractor.OnStart(attrs, newCtx, request)
114  	}
115  	// execute context customizer hook
116  	for _, customizer := range i.contextCustomizers {
117  		newCtx = customizer.OnStart(newCtx, request, attrs)
118  	}
119  	for _, listener := range i.operationListeners {
120  		newCtx = listener.OnBeforeEnd(newCtx, attrs, timestamp)
121  	}
122  	span.SetAttributes(attrs...)
123  	return i.spanSuppressor.StoreInContext(newCtx, spanKind, span)
124  }
